# ---------------------------------------------------------------------------
# Standard Settlement Instructions (SSI)
#
# Each tuple:
#   (beneficiary_bic, beneficiary_bank_name, currency,
#    intermediary_bic, intermediary_bank_name,
#    intermediary_account (Nostro), beneficiary_account (credit-to),
#    charge_code, value_date, notes)
#
# TWO TIERS of data quality:
#  1. REAL — sourced from bank-published SSI pages (Emirates NBD, Bank Danamon,
#     Bank of Ceylon). These carry actual account numbers and are marked with
#     _SSI_REAL_NOTE citing the source.
#  2. PLACEHOLDER — account numbers prefixed ACCT- (synthetic). Marked with
#     _SSI_NOTE. Replace before any real use.
#
# Even "real" published SSIs change over time — always verify against the
# bank's current published page or SWIFTRef before wiring funds.
# ---------------------------------------------------------------------------

